    #[test]
    fn set_root_defaults_and_figure() {
        let mut s = Session::new();
        // `set(0,'Default...',v)` stores a root default `get` reads back.
        s.run("set(0,'DefaultAxesFontName','Times'); fn = get(0,'DefaultAxesFontName');").unwrap();
        assert_eq!(s.get("fn"), Some(&Value::Str("Times".into())));
        // Figure props write the same fields `get` reports.
        s.run("figure; plot(1:3); set(gcf,'ylim',[0 9],'title','t1','grid','on');").unwrap();
        assert_eq!(s.figs[0].ylim, Some((0.0, 9.0)));
        assert_eq!(s.figs[0].title.as_deref(), Some("t1"));
        assert!(s.figs[0].grid);
        s.run("g = get(gcf,'grid');").unwrap();
        assert_eq!(s.get("g"), Some(&Value::Str("on".into())));
        // A non-default root prop is read-only.
        assert!(s.run("set(0,'ScreenSize',[0 0 1 1])").is_err());
    }

    #[test]
    fn argv_empty_cell() {
        let mut s = Session::new();
        s.run("a = argv(); n = numel(a);").unwrap();
        assert_eq!(s.get("n"), Some(&Value::Num(0.0)));
    }

    #[test]
    fn classdef_ctor_props_methods() {
        let mut s = Session::new();
        s.run(
            "classdef Counter
    properties
        value = 0
        tag = 'c'
    end
    methods
        function obj = Counter(v)
            if nargin >= 1
                obj.value = v;
            end
        end
        function y = get(obj)
            y = obj.value;
        end
        function obj = bump(obj, k)
            obj.value = obj.value + k;
        end
    end
end",
        )
        .unwrap();
        // Constructor + property read.
        s.run("c = Counter(5); a = c.value;").unwrap();
        assert_eq!(s.get("a"), Some(&Value::Num(5.0)));
        // Property write.
        s.run("c.value = 7; b = c.value;").unwrap();
        assert_eq!(s.get("b"), Some(&Value::Num(7.0)));
        // Dot-call and function-first method forms both dispatch.
        s.run("d = c.get(); e = get(c);").unwrap();
        assert_eq!(s.get("d"), Some(&Value::Num(7.0)));
        assert_eq!(s.get("e"), Some(&Value::Num(7.0)));
        // Value semantics: a mutating method must be re-assigned.
        s.run("c2 = c.bump(3); f = c2.value; g = c.value;").unwrap();
        assert_eq!(s.get("f"), Some(&Value::Num(10.0)));
        assert_eq!(s.get("g"), Some(&Value::Num(7.0)));
        // class / isa / isobject.
        s.run("n = class(c); t1 = isa(c,'Counter'); t2 = isa(c,'Nope'); t3 = isobject(c); t4 = isobject(3);").unwrap();
        assert_eq!(s.get("n"), Some(&Value::Str("Counter".into())));
        assert_eq!(s.get("t1"), Some(&Value::Num(1.0)));
        assert_eq!(s.get("t2"), Some(&Value::Num(0.0)));
        assert_eq!(s.get("t3"), Some(&Value::Num(1.0)));
        assert_eq!(s.get("t4"), Some(&Value::Num(0.0)));
    }

    #[test]
    fn classdef_attributes_and_sections() {
        let mut s = Session::new();
        // Attribute lists in every form parse; `methods (Static)` drops
        // the implicit object argument.
        s.run(
            "classdef Att < handle
    properties (Access = private, Constant = false)
        a = 1
        b
    end
    properties (SetAccess = protected, GetAccess = public, Dependent)
        c = 2
    end
    properties (Constant)
        k = 7
    end
    methods ( Access = public , Static = false , Abstract = false )
        function obj = Att()
            obj.a = 1;
        end
    end
    methods (Access = private)
        function y = secret(obj)
            y = 42;
        end
    end
    methods (Static)
        function y = twice(x)
            y = 2 * x;
        end
    end
end",
        )
        .unwrap();
        s.run("o = Att(); v = o.c; w = o.twice(4); kk = o.k;").unwrap();
        assert_eq!(s.get("v"), Some(&Value::Num(2.0)));
        assert_eq!(s.get("w"), Some(&Value::Num(8.0)));
        assert_eq!(s.get("kk"), Some(&Value::Num(7.0)));
        // Private reads, Constant writes, Dependent writes and private
        // methods are rejected outside the class.
        s.run(
            "try, q = o.b; catch e, msg = e.message; end\n\
             try, o.k = 8; catch e2, msg2 = e2.message; end\n\
             try, o.c = 5; catch e3, msg3 = e3.message; end\n\
             try, o.secret; catch e4, msg4 = e4.message; end",
        )
        .unwrap();
        let msg = |s: &Session, n: &str| match s.get(n) {
            Some(Value::Str(v)) => v.clone(),
            _ => String::new(),
        };
        assert!(msg(&s, "msg").contains("private access"), "msg = {}", msg(&s, "msg"));
        assert!(msg(&s, "msg2").contains("Constant"), "msg2 = {}", msg(&s, "msg2"));
        assert!(msg(&s, "msg3").contains("Dependent"), "msg3 = {}", msg(&s, "msg3"));
        assert!(msg(&s, "msg4").contains("private access"), "msg4 = {}", msg(&s, "msg4"));
    }

    #[test]
    fn classdef_events_and_listeners() {
        let mut s = Session::new();
        s.run(
            "classdef Emitter < handle
    properties
        hits = 0
    end
    events
        Ping
    end
    methods
        function fire(obj)
            notify(obj, 'Ping');
        end
    end
end
function bump(src, evt)
    src.hits = src.hits + 1;
end",
        )
        .unwrap();
        s.run("e = Emitter(); l = addlistener(e, 'Ping', @bump); e.fire(); n1 = e.hits; ev = events(e);").unwrap();
        assert_eq!(s.get("n1"), Some(&Value::Num(1.0)));
        if let Some(Value::Cell(ev)) = s.get("ev") {
            assert!((0..ev.numel()).any(|i| matches!(ev.get_linear(i), Some(Value::Str(x)) if x == "Ping")));
        } else {
            panic!("events(e) is not a cell");
        }
        s.run("delete(l); notify(e, 'Ping'); n2 = e.hits;").unwrap();
        assert_eq!(s.get("n2"), Some(&Value::Num(1.0)));

        // Value classes cannot own listeners.
        s.run("classdef ValueOnly\n properties\n x = 1\n end\n end").unwrap();
        s.run("v = ValueOnly(); try, addlistener(v, 'Ping', @bump); catch le, lmsg = le.message; end").unwrap();
        if let Some(Value::Str(m)) = s.get("lmsg") {
            assert!(m.contains("handle class"), "listener error = {m}");
        } else {
            panic!("value-class addlistener did not error");
        }
    }

    #[test]
    fn classdef_abstract_and_sealed() {
        let mut s = Session::new();
        s.run(
            "classdef AbsBase
    properties
        x = 1
    end
    methods (Abstract)
        y = compute(obj)
    end
end
classdef AbsImpl < AbsBase
    methods
        function y = compute(obj)
            y = obj.x + 1;
        end
    end
end",
        )
        .unwrap();
        s.run("try, a = AbsBase(); catch ae, amsg = ae.message; end").unwrap();
        if let Some(Value::Str(m)) = s.get("amsg") {
            assert!(m.contains("abstract"), "abstract error = {m}");
        } else {
            panic!("abstract class instantiated");
        }
        s.run("b = AbsImpl(); y = b.compute();").unwrap();
        assert_eq!(s.get("y"), Some(&Value::Num(2.0)));

        s.run("classdef (Sealed) Seal\n properties\n x = 1\n end\n end\nclassdef SealKid < Seal\n end").unwrap();
        s.run("try, sk = SealKid(); catch se, smsg = se.message; end").unwrap();
        if let Some(Value::Str(m)) = s.get("smsg") {
            assert!(m.contains("sealed"), "sealed error = {m}");
        } else {
            panic!("sealed superclass was subclassed");
        }
    }

